-- Generated by `uv run features flink` from features/definitions.yml. Do not edit by hand.
-- Card features (FR-F1, FR-F2, FR-F6): one record per transaction on features.card;
-- transactions behind the 30 s watermark go to dlq.late_events instead.

SET 'pipeline.name' = 'features-card';

SET 'execution.runtime-mode' = 'streaming';

SET 'execution.checkpointing.mode' = 'EXACTLY_ONCE';

SET 'table.local-time-zone' = 'UTC';

CREATE TEMPORARY TABLE pg_transactions (
    `op` STRING,
    `before` ROW<`transaction_id` BIGINT, `card_id` BIGINT, `merchant_id` BIGINT, `amount` DECIMAL(12, 2), `channel` STRING, `lat` DOUBLE, `lon` DOUBLE, `event_ts` STRING>,
    `after` ROW<`transaction_id` BIGINT, `card_id` BIGINT, `merchant_id` BIGINT, `amount` DECIMAL(12, 2), `channel` STRING, `lat` DOUBLE, `lon` DOUBLE, `event_ts` STRING>,
    event_ms AS UNIX_TIMESTAMP(SUBSTRING(COALESCE(`after`.event_ts, `before`.event_ts) FROM 1 FOR 19), 'yyyy-MM-dd''T''HH:mm:ss') * 1000 + CAST(SUBSTRING(CONCAT(COALESCE(REGEXP_EXTRACT(COALESCE(`after`.event_ts, `before`.event_ts), '\.([0-9]+)', 1), ''), '000') FROM 1 FOR 3) AS INT),
    event_time AS TO_TIMESTAMP_LTZ(UNIX_TIMESTAMP(SUBSTRING(COALESCE(`after`.event_ts, `before`.event_ts) FROM 1 FOR 19), 'yyyy-MM-dd''T''HH:mm:ss') * 1000 + CAST(SUBSTRING(CONCAT(COALESCE(REGEXP_EXTRACT(COALESCE(`after`.event_ts, `before`.event_ts), '\.([0-9]+)', 1), ''), '000') FROM 1 FOR 3) AS INT), 3),
    WATERMARK FOR event_time AS event_time - INTERVAL '30' SECOND
) WITH (
    'connector' = 'kafka',
    'topic' = 'pg.public.transactions',
    'properties.bootstrap.servers' = 'redpanda:9092',
    'properties.group.id' = 'features-card',
    'scan.startup.mode' = 'earliest-offset',
    'value.format' = 'avro-confluent',
    'value.avro-confluent.url' = 'http://redpanda:8081'
);

CREATE TEMPORARY VIEW card_txn AS SELECT `after`.transaction_id AS transaction_id, `after`.card_id AS card_id, `after`.merchant_id AS merchant_id, `after`.amount AS amount, `after`.channel AS channel, `after`.lat AS lat, `after`.lon AS lon, event_ms, event_time FROM pg_transactions WHERE op = 'c' AND (CURRENT_WATERMARK(event_time) IS NULL OR event_time >= CURRENT_WATERMARK(event_time));

CREATE TEMPORARY VIEW card_late AS SELECT `after`.transaction_id AS transaction_id, `after`.card_id AS card_id, event_ms, CAST(CURRENT_WATERMARK(event_time) AS STRING) AS watermark_at FROM pg_transactions WHERE op = 'c' AND event_time < CURRENT_WATERMARK(event_time);

CREATE TEMPORARY VIEW card_w_1m AS SELECT transaction_id, event_time, COUNT(*) OVER (PARTITION BY card_id ORDER BY event_time RANGE BETWEEN INTERVAL '1' MINUTE PRECEDING AND CURRENT ROW) AS txn_count_1m FROM card_txn WHERE event_ms > -60000;

CREATE TEMPORARY VIEW card_w_1h AS SELECT transaction_id, event_time, COUNT(*) OVER (PARTITION BY card_id ORDER BY event_time RANGE BETWEEN INTERVAL '1' HOUR PRECEDING AND CURRENT ROW) AS txn_count_1h, CAST(SUM(amount) OVER (PARTITION BY card_id ORDER BY event_time RANGE BETWEEN INTERVAL '1' HOUR PRECEDING AND CURRENT ROW) AS DECIMAL(18, 2)) AS txn_amount_sum_1h, COUNT(DISTINCT merchant_id) OVER (PARTITION BY card_id ORDER BY event_time RANGE BETWEEN INTERVAL '1' HOUR PRECEDING AND CURRENT ROW) AS distinct_merchants_1h FROM card_txn WHERE event_ms > -3600000;

CREATE TEMPORARY VIEW card_w_24h AS SELECT transaction_id, event_time, COUNT(*) OVER (PARTITION BY card_id ORDER BY event_time RANGE BETWEEN INTERVAL '24' HOUR PRECEDING AND CURRENT ROW) AS txn_count_24h, CAST(SUM(amount) OVER (PARTITION BY card_id ORDER BY event_time RANGE BETWEEN INTERVAL '24' HOUR PRECEDING AND CURRENT ROW) AS DECIMAL(18, 2)) AS txn_amount_sum_24h FROM card_txn WHERE event_ms > -86400000;

CREATE TEMPORARY VIEW card_w_30d AS SELECT transaction_id, event_time, COUNT(*) OVER (PARTITION BY card_id ORDER BY event_time RANGE BETWEEN INTERVAL '30' DAY PRECEDING AND CURRENT ROW) AS amount_vs_avg_30d__n, SUM(amount) OVER (PARTITION BY card_id ORDER BY event_time RANGE BETWEEN INTERVAL '30' DAY PRECEDING AND CURRENT ROW) AS amount_vs_avg_30d__sum FROM card_txn WHERE event_ms > -2592000000;

CREATE TEMPORARY VIEW card_prev AS SELECT transaction_id, event_time, event_ms, lat, lon, COUNT(*) OVER (PARTITION BY card_id ORDER BY event_time ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS n, SUM(lat) OVER (PARTITION BY card_id ORDER BY event_time ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS lat_sum, SUM(lon) OVER (PARTITION BY card_id ORDER BY event_time ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS lon_sum, SUM(event_ms) OVER (PARTITION BY card_id ORDER BY event_time ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS ms_sum FROM card_txn WHERE channel = 'card_present';

CREATE TEMPORARY TABLE features_card (card_key STRING, transaction_id BIGINT, card_id BIGINT, event_ms BIGINT, txn_count_1m BIGINT, txn_count_1h BIGINT, txn_count_24h BIGINT, txn_amount_sum_1h DECIMAL(18, 2), txn_amount_sum_24h DECIMAL(18, 2), distinct_merchants_1h BIGINT, amount_vs_avg_30d DOUBLE, km_from_last_txn DOUBLE, minutes_since_last_txn DOUBLE, definitions_version INT, computed_at STRING) WITH (
    'connector' = 'kafka',
    'topic' = 'features.card',
    'properties.bootstrap.servers' = 'redpanda:9092',
    'key.format' = 'raw',
    'key.fields' = 'card_key',
    'value.format' = 'avro-confluent',
    'value.avro-confluent.url' = 'http://redpanda:8081',
    'value.fields-include' = 'EXCEPT_KEY',
    'sink.delivery-guarantee' = 'at-least-once'
);

CREATE TEMPORARY TABLE late_events (source_topic STRING, transaction_id BIGINT, card_id BIGINT, event_ms BIGINT, watermark_at STRING, detected_at STRING) WITH (
    'connector' = 'kafka',
    'topic' = 'dlq.late_events',
    'properties.bootstrap.servers' = 'redpanda:9092',
    'format' = 'json',
    'sink.delivery-guarantee' = 'at-least-once'
);

EXECUTE STATEMENT SET
BEGIN
INSERT INTO features_card SELECT CAST(card_id AS STRING), transaction_id, card_id, event_ms, txn_count_1m, txn_count_1h, txn_count_24h, txn_amount_sum_1h, txn_amount_sum_24h, distinct_merchants_1h, amount_vs_avg_30d, km_from_last_txn, minutes_since_last_txn, 1, DATE_FORMAT(CAST(CURRENT_TIMESTAMP AS TIMESTAMP(3)), 'yyyy-MM-dd''T''HH:mm:ss.SSS''Z''') FROM (SELECT t.transaction_id, t.card_id, t.event_ms, CAST(card_w_1m.txn_count_1m AS BIGINT) AS txn_count_1m, CAST(card_w_1h.txn_count_1h AS BIGINT) AS txn_count_1h, CAST(card_w_24h.txn_count_24h AS BIGINT) AS txn_count_24h, CAST(card_w_1h.txn_amount_sum_1h AS DECIMAL(18, 2)) AS txn_amount_sum_1h, CAST(card_w_24h.txn_amount_sum_24h AS DECIMAL(18, 2)) AS txn_amount_sum_24h, CAST(card_w_1h.distinct_merchants_1h AS BIGINT) AS distinct_merchants_1h, CAST(CASE WHEN card_w_30d.amount_vs_avg_30d__n > 1 THEN CAST(t.amount AS DOUBLE) / (CAST(card_w_30d.amount_vs_avg_30d__sum - t.amount AS DOUBLE) / (card_w_30d.amount_vs_avg_30d__n - 1)) END AS DOUBLE) AS amount_vs_avg_30d, CAST(CASE WHEN p.n = 2 THEN 2 * 6371.0088 * ASIN(SQRT(POWER(SIN(RADIANS(p.lat - (p.lat_sum - p.lat)) / 2), 2) + COS(RADIANS((p.lat_sum - p.lat))) * COS(RADIANS(p.lat)) * POWER(SIN(RADIANS(p.lon - (p.lon_sum - p.lon)) / 2), 2))) END AS DOUBLE) AS km_from_last_txn, CAST(CASE WHEN p.n = 2 THEN CAST(t.event_ms - (p.ms_sum - p.event_ms) AS DOUBLE) / 60000.0 END AS DOUBLE) AS minutes_since_last_txn FROM card_txn t JOIN card_w_1m ON card_w_1m.transaction_id = t.transaction_id AND card_w_1m.event_time BETWEEN t.event_time AND t.event_time JOIN card_w_1h ON card_w_1h.transaction_id = t.transaction_id AND card_w_1h.event_time BETWEEN t.event_time AND t.event_time JOIN card_w_24h ON card_w_24h.transaction_id = t.transaction_id AND card_w_24h.event_time BETWEEN t.event_time AND t.event_time JOIN card_w_30d ON card_w_30d.transaction_id = t.transaction_id AND card_w_30d.event_time BETWEEN t.event_time AND t.event_time LEFT JOIN card_prev p ON p.transaction_id = t.transaction_id AND p.event_time BETWEEN t.event_time AND t.event_time);
INSERT INTO late_events SELECT 'pg.public.transactions', transaction_id, card_id, event_ms, watermark_at, DATE_FORMAT(CAST(CURRENT_TIMESTAMP AS TIMESTAMP(3)), 'yyyy-MM-dd''T''HH:mm:ss.SSS''Z''') FROM card_late;
END;
